        "eye.intro.page1.subtitle": "Не просто тренажёр — умная пауза",
        "eye.intro.page1.body": "Lippi объединяет короткие упражнения, бережную оценку комфорта и подходящий момент для отдыха, чтобы поддерживать взгляд без лишнего давления.",
