        "eye.intro.depth.fact1.body": "Depth guidance tells you when to move iPhone closer or farther away for a dependable exercise.",
        "eye.intro.depth.fact2.title": "Steadier eye tracking",
        "eye.intro.depth.fact2.body": "Head position and lighting are checked first, making gaze movement easier to follow accurately.",
        "eye.intro.page3.title": "Privacy is built in",
        "eye.intro.page3.subtitle": "Everything important happens on iPhone",
        "eye.intro.page3.body": "Lippi never accesses Face ID, identifies you, or creates a face template. Frames and depth maps are neither saved nor sent.",
        "eye.intro.private.fact1.title": "On-device processing",
        "eye.intro.private.fact1.body": "The camera and Vision run only during an exercise, directly on your device.",
        "eye.intro.private.fact2.title": "No facial profile",
        "eye.intro.private.fact2.body": "Only anonymous exercise results can inform suggestions — never images or biometric data.",
        "eye.intro.page4.title": "Care adapts to you",
        "eye.intro.page4.subtitle": "Focus, recovery, and wellbeing work together",
        "eye.intro.page4.body": "Lippi considers focus duration, exercise results, and available wellbeing signals to suggest a useful next step.",
        "eye.intro.care.fact1.title": "Lippi intelligence",
        "eye.intro.care.fact1.body": "Bonsai can notice recurring signs of strain and help shape a gentler rhythm for your day.",
        "eye.intro.care.fact2.title": "You stay in control",
        "eye.intro.care.fact2.body": "The app may suggest rest, water, or a short exercise, but changes nothing without your action.",

